{
public:
    Monster() { }
    Monster(const Monster&) { }
    ~Monster() { }

    static int alive() { return 0; }

private:
    static inline int s_alive{ 0 };
};

solution.solution.cpp:
class Monster
{
public:
    Monster() { ++s_alive; }
    Monster(const Monster&) { ++s_alive; }
    ~Monster() { --s_alive; }

    static int alive() { return s_alive; }

private:
    static inline int s_alive{ 0 };
};

unitTests:
TEST("counts objects as they come and go") {
    CHECK_EQ(Monster::alive(), 0);
    {
        Monster a{};
        Monster b{};
        CHECK_EQ(Monster::alive(), 2);
        {
            Monster c{ a };
            CHECK_EQ(Monster::alive(), 3);
        }
        CHECK_EQ(Monster::alive(), 2);
    }
    CHECK_EQ(Monster::alive(), 0);
}

